    if (!parsed.success) {
      return NextResponse.json({ error: "validation_error", message: "Invalid request body" }, { status: 400 });
    }
    const { email, password } = parsed.data;
    const ok = email === "admin@example.com" && password === "password123";
    if (!ok) return NextResponse.json({ error: "auth_error", message: "Invalid credentials" }, { status: 401 });
    const res = NextResponse.json({ ok: true });
    res.cookies.set("session", "valid-session", { httpOnly: true, sameSite: "lax", secure: process.env.NODE_ENV === "production", path: "/", maxAge: 60 * 60 * 24 });
    return res;
  } catch {
    return NextResponse.json({ error: "server_error", message: "Unexpected error" }, { status: 500 });
  }
